head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.arrSubmit = [];
scwin.arrTimer = [];

// 다운로드 요청은 숨겨진 iframe 으로 form 이 전송되어 발생한다.
//  화면에서는 요청 발생 여부를 볼 수 없으므로 form 전송을 가로채 기록만 남긴다(전송은 그대로 진행된다).
scwin.onpageload = function () {
    let fnOrigin = HTMLFormElement.prototype.submit;

    HTMLFormElement.prototype.submit = function () {
        scwin.arrSubmit.push(this.action || "");
        return fnOrigin.apply(this, arguments);
    };
};



// 확인창은 최상위 문서가 아니라 iframe#gridDownLoadLayer 안에 있다.
//  iframe 자체의 표시 여부와 그 안의 download 버튼 표시 여부를 함께 읽는다.
scwin.getDialogState = function () {
    let objFrame = document.getElementById("gridDownLoadLayer");
    let objModal = document.getElementById("_modal");
    let sFrame = "없음";
    let sButton = "확인 불가";

    if (objFrame !== null) {
        sFrame = ((objFrame.style.display !== "none" && objFrame.offsetParent !== null) ? "표시됨" : "표시 안 됨");

        try {
            let objDoc = objFrame.contentDocument;
            let objButton = ((objDoc === null) ? null : objDoc.getElementById("downloadButton"));
            sButton = ((objButton === null) ? "없음" : ((objButton.offsetParent !== null) ? "표시됨" : "표시 안 됨"));
        } catch (e) {
            sButton = "확인 불가";
        }
    }

    return "확인창 iframe : " + sFrame
        + " / download 버튼 : " + sButton
        + " / 화면 모달 : " + ((objModal === null) ? "없음" : ((objModal.style.display !== "none") ? "표시됨" : "표시 안 됨"))
        + " / 다운로드 요청 : " + ((scwin.arrSubmit.length === 0) ? "없음" : "발생");
};



scwin.clearTimer = function () {
    for (let i = 0; i < scwin.arrTimer.length; i++) {
        clearTimeout(scwin.arrTimer[i]);
    }
    scwin.arrTimer = [];
};



// 확인창 안의 download 버튼을 사용자가 클릭하면 그 시점부터 1.5 초 간격으로 5 회 확인창 상태를 기록한다.
//  버튼 클릭 자체는 가로채지 않고 그대로 진행된다(상태를 읽기만 한다).
scwin.watchDialog = function (sCase) {
    let nTry = 0;

    let fnAttach = function () {
        let objFrame = document.getElementById("gridDownLoadLayer");
        let objDoc = null;

        try {
            objDoc = ((objFrame === null) ? null : objFrame.contentDocument);
        } catch (e) {
            objDoc = null;
        }

        let objButton = ((objDoc === null) ? null : objDoc.getElementById("downloadButton"));

        if (objButton === null) {
            if (++nTry < 40) {
                scwin.arrTimer.push(setTimeout(fnAttach, 250));
            } else {
                scwin.setReturnValue(sCase + " 확인창이 표시되지 않음 : " + scwin.getDialogState());
            }
            return;
        }

        scwin.setReturnValue(sCase + " 확인창 표시 직후 : " + scwin.getDialogState());

        objButton.addEventListener("click", function () {
            for (let i = 1; i <= 5; i++) {
                (function (nStep) {
                    scwin.arrTimer.push(setTimeout(function () {
                        scwin.setReturnValue(sCase + " download 클릭 +" + (nStep * 1.5) + "초 : " + scwin.getDialogState());
                    }, nStep * 1500));
                })(i);
            }
        }, true);
    };

    fnAttach();
};



// [A] 대조군 : showProcess 를 전달하지 않고 showConfirm 만 true 로 설정한다.
scwin.btn_a_onclick = function () {
    scwin.clearTimer();
    scwin.arrSubmit = [];

    target1.advancedExcelDownload({
        "fileName" : "fail_dialogNotClosed_A",
        "extension" : "xlsx",
        "showConfirm" : true
    });

    scwin.setReturnValue("[A] showConfirm=true (showProcess 미설정)");
    scwin.watchDialog("[A]");
};



// [B] 결함 : showProcess 를 false 로, showConfirm 을 true 로 함께 설정한다.
scwin.btn_b_onclick = function () {
    scwin.clearTimer();
    scwin.arrSubmit = [];

    target1.advancedExcelDownload({
        "fileName" : "fail_dialogNotClosed_B",
        "extension" : "xlsx",
        "showProcess" : false,
        "showConfirm" : true
    });

    scwin.setReturnValue("[B] showProcess=false / showConfirm=true");
    scwin.watchDialog("[B]");
};



// 현재 확인창 상태를 한 번 더 읽는다(상태 조회 전용).
scwin.btn_state_onclick = function () {
    scwin.setReturnValue("[현재 상태] " + scwin.getDialogState());
};
